"""Build the VI review book and independently reusable application canvases."""
from pathlib import Path
import json

HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[3]
OUT=ROOT/'output/wqt-vi-v3'

def image(name,cls='',style=''):
    return f'<img src="assets/{name}" class="{cls}" style="{style}" alt="{name}">'
def logo(cls='logo'):
    return image('company-mark.png',cls)
def badge(cls='badge'):
    return image('program-badge-s2.png',cls)
def frame(cls='',color='#86B7FF'):
    return f'<svg class="frame {cls}" viewBox="0 0 600 700" preserveAspectRatio="none" fill="none"><path d="M30 2H568L598 32V668L568 698H30L2 668V32Z" stroke="{color}" stroke-width="2"/><path d="M42 12H557L588 43V655L557 688H42L12 655V43Z" stroke="{color}" stroke-opacity=".32"/><path d="M30 2H138M598 94V190M460 698H568M2 510V607" stroke="#EEF7FF" stroke-width="4"/></svg>'
def flow(cls=''):
    return f'<svg class="flow {cls}" viewBox="0 0 1200 600" fill="none" preserveAspectRatio="none">'+''.join(f'<path d="M-50 {130+i*15} C 250 {460+i*9}, 600 {120+i*15}, 1250 {360+i*11}" stroke="currentColor" stroke-width="{1 if i%4 else 2}" opacity="{.17 if i%4 else .6}"/>' for i in range(12))+'</svg>'
def header(kicker,title,note=''):
    return f'<header><div class="eyebrow">{kicker}</div><h2>{title}</h2><p class="head-note">{note}</p></header>'
def board(n,body,cls=''):
    return f'<section class="board {cls}" id="page-{n:02d}">{body}<footer><span>伍仟天科技 · VISUAL IDENTITY</span><span>2026.10 / V3 · 设计提案</span><span>{n:02d} / 12</span></footer></section>'
def wrap_art(name,scale,x,y):
    return f'<div class="mock" style="left:{x}px;top:{y}px;width:{ARTS[name][0]*scale}px;height:{ARTS[name][1]*scale}px"><div style="transform:scale({scale});transform-origin:top left">{ARTS[name][2]}</div></div>'

